import subprocess,re
def sh(*a): return subprocess.run(['git','-C','/home/runner/chandler-wt']+list(a),capture_output=True,text=True).stdout
hs = sh('log','--format=%H','origin/friend/chandler').split()
prob=[]; n=0
for h in hs:
    b = sh('log','-1','--format=%B',h)
    if 'Friend-Message: 1' not in b: continue
    n+=1
    lines=b.strip().splitlines()
    ri=[i for i,l in enumerate(lines) if l.startswith('Reply-To:')]
    if not ri: prob.append((h[:8],'no Reply-To')); continue
    utt=lines[ri[0]+1:]
    while utt and utt[0].strip()=='': utt.pop(0)
    if not utt or not utt[0].startswith('Chandler: '): prob.append((h[:8],'utt start: '+str(utt[:1])))
    for l in utt:
        for sp in ('Rachel: ','Monica: ','Phoebe: ','Joey: ','Ross: '):
            if sp in l: prob.append((h[:8],'other speaker: '+l[:40]))
print('utterances checked:',n,'problems:',prob)
