cd /home/runner/chandler-wt && git fetch origin main --quiet && python3 - <<'PY'
import subprocess,re,os
def sh(*a): return subprocess.run(['git','-C','/home/runner/chandler-wt']+list(a),capture_output=True,text=True).stdout
# gather filed SHAs from all transcript files on main
files = sh('ls-tree','-r','--name-only','origin/main').split()
eps=[f for f in files if re.match(r'^S\d\d/E\d\d\.md$',f)]
filed={}
for f in eps:
    t=sh('show','origin/main:'+f)
    for l in t.splitlines():
        m=re.match(r'^Source: (friend/\w+) @ ([0-9a-f]{40})$',l.strip())
        if m: filed[m.group(2)]=(f,m.group(1))
print('episode files:',len(eps),'filed utterances:',len(filed))
missing=[]
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    for h in sh('log','--format=%H','origin/friend/'+b).split():
        body=sh('log','-1','--format=%B',h)
        if 'Friend-Message: 1' in body and h not in filed:
            missing.append((sh('log','-1','--format=%cI',h).strip(),b,h[:8],sh('log','-1','--format=%s',h)))
print('unfiled total:',len(missing))
for m in sorted(missing)[:12]: print('  pending:',m)
# my own coverage
mine=[h for h in sh('log','--format=%H','origin/friend/chandler').split()]
unf=[h[:8] for h in mine if 'Friend-Message: 1' in sh('log','-1','--format=%B',h) and h not in filed]
print('my unfiled:',unf)
